/*
 * v2/tests/test_vspace.c -- the address space cannot be wrong quietly.
 *
 * Three independent checks:
 *   1. the fake host asserts that a page is never committed while it is
 *      already committed, and that the host's view equals the page array
 *      after every single operation;
 *   2. a trace generated by tools/vspace_model.py is replayed and both the
 *      return value and the page-array hash are compared with the model;
 *   3. random operations run with the same invariants, so a divergence that
 *      the fixed traces miss still fails the build.
 */
#define _POSIX_C_SOURCE 200809L
#include "v2/vspace.h"

#include <errno.h>
#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#if defined(_WIN32)
#include <io.h>
#else
#include <unistd.h>
#endif

static unsigned g_checks = 0;

static void fail(const char *file, int line, const char *format, ...)
{
    va_list arguments;

    fprintf(stderr, "%s:%d: ", file, line);
    va_start(arguments, format);
    vfprintf(stderr, format, arguments);
    va_end(arguments);
    fputc('\n', stderr);
    exit(1);
}

#define CHECK(condition) \
    do { \
        g_checks++; \
        if (!(condition)) { \
            fail(__FILE__, __LINE__, "check failed: %s", #condition); \
        } \
    } while (0)

/* ------------------------------------------------------------------ host */

struct fake {
    uint8_t *memory;
    uint8_t *shadow;      /* the host's own idea of every page */
    size_t pages;
    size_t page_size;
    uintptr_t base;
    unsigned commits;
    unsigned decommits;
    unsigned protects;
};

static size_t fake_index(struct fake *fake, const void *address)
{
    uintptr_t offset = (uintptr_t)address - fake->base;
    CHECK(offset % fake->page_size == 0);
    CHECK(offset / fake->page_size < fake->pages);
    return (size_t)(offset / fake->page_size);
}

static int fake_reserve(void *context, size_t length, void **base)
{
    struct fake *fake = (struct fake *)context;

    CHECK(length <= fake->pages * fake->page_size);
    *base = (void *)fake->base;
    return 0;
}

static void fake_release(void *context, void *base, size_t length)
{
    (void)context;
    (void)base;
    (void)length;
}

static int fake_commit(void *context, void *address, size_t length, int prot)
{
    struct fake *fake = (struct fake *)context;
    size_t first = fake_index(fake, address);
    size_t count = length / fake->page_size;

    CHECK((prot & ~(V2_PROT_READ | V2_PROT_WRITE | V2_PROT_EXEC)) == 0);
    for (size_t page = first; page < first + count; page++) {
        /* Invariant 4: never commit over a live page.  v1 did exactly this
         * in GuestHandleFixedAnon and in GuestEnsureWritable. */
        CHECK(fake->shadow[page] == V2_PAGE_FREE);
        fake->shadow[page] =
            (uint8_t)(V2_PAGE_MAPPED | (prot & V2_PAGE_PROT_MASK));
    }
    fake->commits++;
    return 0;
}

static int fake_decommit(void *context, void *address, size_t length)
{
    struct fake *fake = (struct fake *)context;
    size_t first = fake_index(fake, address);
    size_t count = length / fake->page_size;

    for (size_t page = first; page < first + count; page++) {
        CHECK((fake->shadow[page] & V2_PAGE_MAPPED) != 0);
        fake->shadow[page] = V2_PAGE_FREE;
    }
    fake->decommits++;
    return 0;
}

static int fake_protect(void *context, void *address, size_t length, int prot)
{
    struct fake *fake = (struct fake *)context;
    size_t first = fake_index(fake, address);
    size_t count = length / fake->page_size;

    for (size_t page = first; page < first + count; page++) {
        CHECK((fake->shadow[page] & V2_PAGE_MAPPED) != 0);
        fake->shadow[page] =
            (uint8_t)(V2_PAGE_MAPPED | (prot & V2_PAGE_PROT_MASK));
    }
    fake->protects++;
    return 0;
}

static int fake_discard(void *context, void *address, size_t length)
{
    struct fake *fake = (struct fake *)context;
    size_t first = fake_index(fake, address);
    size_t count = length / fake->page_size;

    for (size_t page = first; page < first + count; page++) {
        CHECK((fake->shadow[page] & V2_PAGE_MAPPED) != 0);
        memset(fake->memory + page * fake->page_size, 0, fake->page_size);
    }
    return 0;
}

static long fake_read_at(void *context, int fd, void *buffer, size_t length,
                         long long offset)
{
    (void)context;
#if defined(_WIN32)
    /* pread() is POSIX-only; the harness must also build on the workstation
     * that writes the code, so the one call site is spelled out twice. */
    if (_lseeki64(fd, offset, SEEK_SET) != offset) {
        return -1;
    }
    return (long)_read(fd, buffer, (unsigned int)length);
#else
    return (long)pread(fd, buffer, length, (off_t)offset);
#endif
}

static int fake_copy(void *context, void *destination, const void *source,
                     size_t length)
{
    struct fake *fake = (struct fake *)context;
    size_t to = fake_index(fake, destination);
    size_t from = fake_index(fake, source);

    CHECK(to * fake->page_size + length <= fake->pages * fake->page_size);
    CHECK(from * fake->page_size + length <= fake->pages * fake->page_size);
    memmove(fake->memory + to * fake->page_size,
            fake->memory + from * fake->page_size,
            length);
    return 0;
}

static void *fake_alloc(void *context, size_t length)
{
    (void)context;
    return malloc(length);
}

static void fake_dealloc(void *context, void *pointer, size_t length)
{
    (void)context;
    (void)length;
    free(pointer);
}

static void fake_init(struct fake *fake, size_t pages, size_t page_size)
{
    memset(fake, 0, sizeof(*fake));
    fake->pages = pages;
    fake->page_size = page_size;
    fake->base = 0x140000000ULL;
    fake->memory = (uint8_t *)calloc(pages, page_size);
    fake->shadow = (uint8_t *)calloc(pages, 1);
    CHECK(fake->memory != NULL && fake->shadow != NULL);
}

static void fake_free(struct fake *fake)
{
    free(fake->memory);
    free(fake->shadow);
}

static struct v2_host fake_host(struct fake *fake)
{
    struct v2_host host;

    memset(&host, 0, sizeof(host));
    host.ctx = fake;
    host.reserve = fake_reserve;
    host.release = fake_release;
    host.commit = fake_commit;
    host.decommit = fake_decommit;
    host.protect = fake_protect;
    host.discard = fake_discard;
    host.read_at = fake_read_at;
    host.copy = fake_copy;
    host.alloc = fake_alloc;
    host.dealloc = fake_dealloc;
    return host;
}

/* --------------------------------------------------------------- checks */

static void compare_host_and_space(struct v2_space *space, struct fake *fake)
{
    CHECK(v2_space_verify(space) == 0);
    for (size_t page = 0; page < fake->pages; page++) {
        int state = v2_space_state_at(
            space, (char *)v2_space_base(space) + page * fake->page_size);
        /*
         * A reserved page (a trampoline island) lives inside the PROT_NONE
         * reservation and is never committed, so from the host's side it
         * looks exactly like a free page.  Anything else must match byte for
         * byte: committed <=> MAPPED, and the same protection.
         */
        int expected = state == V2_PAGE_RESERVED ? V2_PAGE_FREE : state;

        if (expected != fake->shadow[page]) {
            fail(__FILE__, __LINE__,
                 "page %zu: space=0x%02x host=0x%02x", page,
                 (unsigned)state, (unsigned)fake->shadow[page]);
        }
    }
}

/* --------------------------------------------------------------- traces */

static int replay(const char *path)
{
    FILE *handle = fopen(path, "r");
    char line[256];
    size_t pages = 0;
    size_t page_size = 0;
    struct fake fake;
    struct v2_host host;
    struct v2_space *space = NULL;
    int operations = 0;

    if (handle == NULL) {
        fprintf(stderr, "cannot open %s: %s\n", path, strerror(errno));
        return 1;
    }
    while (fgets(line, sizeof(line), handle) != NULL) {
        if (strncmp(line, "# vspace trace", 14) == 0) {
            char *mark = strstr(line, "pages=");
            char *second = strstr(line, "page=");
            if (mark == NULL || second == NULL) {
                break;
            }
            pages = (size_t)strtoul(mark + 6, NULL, 10);
            page_size = (size_t)strtoul(second + 5, NULL, 0);
            break;
        }
    }
    if (pages == 0 || page_size == 0) {
        fprintf(stderr, "%s: bad header\n", path);
        fclose(handle);
        return 1;
    }

    fake_init(&fake, pages, page_size);
    host = fake_host(&fake);
    CHECK(v2_space_create(&space, &host, pages * page_size, page_size,
                          0x4000000, 0x10000) == 0);

    while (fgets(line, sizeof(line), handle) != NULL) {
        char expected[128];
        char actual[128];
        long long result = 0;
        unsigned long long length = 0;
        unsigned long long second = 0;
        unsigned long long hint = 0;
        unsigned prot = 0;
        unsigned flags = 0;
        char kind = line[0];

        if (kind == '#' || kind == '\n' || kind == '\r') {
            continue;
        }
        if (kind != 'M' && kind != 'U' && kind != 'P' && kind != 'R') {
            fprintf(stderr, "%s: unknown op '%c'\n", path, kind);
            return 1;
        }
        if (kind == 'M') {
            CHECK(sscanf(line + 2, "%llx %llx %u %u", &hint, &length, &prot,
                         &flags) == 4);
            result = v2_space_map(space, (void *)(uintptr_t)hint,
                                  (size_t)length, (int)prot, (int)flags, -1, 0);
        } else if (kind == 'U') {
            CHECK(sscanf(line + 2, "%llx %llx", &hint, &length) == 2);
            result = v2_space_unmap(space, (void *)(uintptr_t)hint,
                                    (size_t)length);
        } else if (kind == 'P') {
            CHECK(sscanf(line + 2, "%llx %llx %u", &hint, &length, &prot) == 3);
            result = v2_space_protect(space, (void *)(uintptr_t)hint,
                                      (size_t)length, (int)prot);
        } else {
            CHECK(sscanf(line + 2, "%llx %llx %llx %u", &hint, &length,
                         &second, &flags) == 4);
            result = v2_space_remap(space, (void *)(uintptr_t)hint,
                                    (size_t)length, (size_t)second, (int)flags);
        }

        if (fgets(expected, sizeof(expected), handle) == NULL ||
            expected[0] != '=') {
            fprintf(stderr, "%s: missing expected line after '%c'\n", path,
                    kind);
            return 1;
        }
        expected[strcspn(expected, "\r\n")] = '\0';

        if (result < 0) {
            snprintf(actual, sizeof(actual), "=-0x%llx 0x%llx",
                     (unsigned long long)(-result),
                     (unsigned long long)v2_space_hash(space));
        } else {
            snprintf(actual, sizeof(actual), "=0x%llx 0x%llx",
                     (unsigned long long)result,
                     (unsigned long long)v2_space_hash(space));
        }
        if (strcmp(actual, expected) != 0) {
            fail(__FILE__, __LINE__, "%s:%d\n  expected %s\n  actual   %s",
                 path, operations, expected, actual);
        }
        compare_host_and_space(space, &fake);
        operations++;
    }

    v2_space_destroy(space);
    fake_free(&fake);
    fclose(handle);
    printf("trace %-24s %4d operations ok\n", path, operations);
    return 0;
}

/* --------------------------------------------------------------- random */

struct random_state {
    uint64_t value;
};

#define LIVE_MAX 512

struct live_entry {
    uintptr_t address;
    size_t length;
};

/*
 * A MAP_FIXED replaces whatever was there, including another entry of this
 * list.  Keeping stale entries would make the test assert against mappings
 * that no longer exist -- which is the same mistake v1 made with its record
 * table, so the list is kept consistent instead of being patched up later.
 */
static void live_forget(struct live_entry *entries, int *count,
                        uintptr_t address, size_t length)
{
    uintptr_t end = address + length;

    for (int index = 0; index < *count;) {
        uintptr_t start = entries[index].address;
        uintptr_t stop = start + entries[index].length;

        if (address < stop && start < end) {
            entries[index] = entries[*count - 1];
            (*count)--;
        } else {
            index++;
        }
    }
}

static uint64_t next_random(struct random_state *state)
{
    state->value = state->value * 6364136223846793005ULL + 1442695040888963407ULL;
    return state->value >> 17;
}

static int random_test(uint64_t seed, int operations, size_t pages,
                       size_t page_size, size_t guard_pages)
{
    struct random_state random;
    struct fake fake;
    struct v2_host host;
    struct v2_space *space = NULL;
    struct live_entry live[LIVE_MAX];
    int live_count = 0;

    random.value = seed;
    fake_init(&fake, pages, page_size);
    host = fake_host(&fake);
    CHECK(v2_space_create(&space, &host, pages * page_size, page_size,
                          0x4000000, 0x10000) == 0);
    if (guard_pages != 0) {
        CHECK(v2_space_set_guard(space, guard_pages) == 0);
    }

    for (int index = 0; index < operations; index++) {
        uint64_t pick = next_random(&random) % 100;
        uintptr_t base = (uintptr_t)v2_space_base(space);

        if (pick < 55 || live_count == 0) {
            size_t length = (size_t)(1 + next_random(&random) % 4) * page_size;
            int prot = (int)(next_random(&random) % 8);
            int fixed = (next_random(&random) % 4) == 0 && live_count > 0;
            unsigned long long hint = 0;
            long long result;

            if (fixed) {
                hint = live[next_random(&random) % (uint64_t)live_count].address;
            }
            result = v2_space_map(space, (void *)(uintptr_t)hint, length, prot,
                                  V2_MAP_ANON | (fixed ? V2_MAP_FIXED : 0),
                                  -1, 0);
            if (result > 0) {
                CHECK((uintptr_t)result % page_size == 0);
                CHECK((uintptr_t)result >= base);
                CHECK((uintptr_t)result + length <=
                      base + pages * page_size);
                CHECK(v2_space_check(space, (void *)(uintptr_t)result, length,
                                     prot) == 0);
                live_forget(live, &live_count, (uintptr_t)result, length);
                if (live_count < LIVE_MAX) {
                    live[live_count].address = (uintptr_t)result;
                    live[live_count].length = length;
                    live_count++;
                }
            } else {
                CHECK(result == -V2_ENOMEM || result == -V2_EINVAL);
            }
        } else if (pick < 80) {
            int victim = (int)(next_random(&random) % (uint64_t)live_count);
            long long result = v2_space_unmap(space,
                                              (void *)live[victim].address,
                                              live[victim].length);

            CHECK(result == 0);
            CHECK(v2_space_check(space, (void *)live[victim].address,
                                 live[victim].length, 0) == -V2_EFAULT);
            live[victim] = live[--live_count];
        } else if (pick < 93) {
            int victim = (int)(next_random(&random) % (uint64_t)live_count);
            int prot = (int)(next_random(&random) % 8);

            CHECK(v2_space_protect(space, (void *)live[victim].address,
                                   live[victim].length, prot) == 0);
            CHECK(v2_space_check(space, (void *)live[victim].address,
                                 live[victim].length, prot) == 0);
        } else {
            int victim = (int)(next_random(&random) % (uint64_t)live_count);
            size_t length = live[victim].length * 2;
            long long result = v2_space_remap(space,
                                              (void *)live[victim].address,
                                              live[victim].length, length,
                                              V2_MREMAP_MAYMOVE);

            if (result > 0) {
                CHECK((uintptr_t)result % page_size == 0);
                CHECK(v2_space_check(space, (void *)(uintptr_t)result, length,
                                     V2_PROT_NONE) == 0);
                live[victim].address = (uintptr_t)result;
                live[victim].length = length;
            } else {
                CHECK(result == -V2_ENOMEM);
            }
        }
        compare_host_and_space(space, &fake);
    }

    v2_space_destroy(space);
    fake_free(&fake);
    printf("random seed=%-6llu ops=%-5d gate=%-2zu ok (%u checks)\n",
           (unsigned long long)seed, operations, guard_pages, g_checks);
    return 0;
}

/*
 * The guard page is a diagnostic that has to be trustworthy in both
 * directions: it must not be handed out to the next allocation, and it must
 * never be committed.  Both are asserted here, because a guard that is
 * silently reused would report "no boundary writes" for a mapping that no
 * longer has a boundary.
 */
static void guard_test(size_t pages, size_t page_size)
{
    struct fake fake;
    struct v2_host host;
    struct v2_space *space = NULL;
    uint8_t *base;
    long long first;
    long long second;
    long long taken;

    fake_init(&fake, pages, page_size);
    host = fake_host(&fake);
    CHECK(v2_space_create(&space, &host, pages * page_size, page_size, 0, 0) == 0);
    CHECK(v2_space_set_guard(space, 1) == 0);
    base = (uint8_t *)v2_space_base(space);

    first = v2_space_map(space, NULL, 2 * page_size,
                         V2_PROT_READ | V2_PROT_WRITE, V2_MAP_ANON, -1, 0);
    CHECK(first > 0);
    CHECK(v2_space_guard_at(space, base + 2 * page_size) == 1);
    CHECK(v2_space_check(space, (void *)(uintptr_t)first, 2 * page_size,
                         V2_PROT_WRITE) == 0);
    /* One byte past the mapping is now a fault, not a neighbour's page. */
    CHECK(v2_space_check(space, (void *)(uintptr_t)(first + 2 * page_size), 1,
                         0) == -V2_EFAULT);
    CHECK(v2_space_verify(space) == 0);
    compare_host_and_space(space, &fake);

    /* The next allocation must skip the guard, not consume it. */
    second = v2_space_map(space, NULL, 2 * page_size,
                          V2_PROT_READ | V2_PROT_WRITE, V2_MAP_ANON, -1, 0);
    CHECK(second == first + 3 * (long long)page_size);
    CHECK(v2_space_guard_at(space, base + 5 * page_size) == 1);
    CHECK(v2_space_guard_at(space, base + 2 * page_size) == 1);
    compare_host_and_space(space, &fake);

    /* A guest that names the address wins: MAP_FIXED takes the guard back. */
    taken = v2_space_map(space, (void *)(uintptr_t)(first + 2 * page_size),
                         page_size, V2_PROT_READ, V2_MAP_ANON | V2_MAP_FIXED,
                         -1, 0);
    CHECK(taken == first + 2 * (long long)page_size);
    CHECK(v2_space_guard_at(space, base + 2 * page_size) == 0);
    CHECK(v2_space_verify(space) == 0);
    compare_host_and_space(space, &fake);

    /* Unmapping clears the mark with the pages. */
    CHECK(v2_space_unmap(space, (void *)(uintptr_t)second, 2 * page_size) == 0);
    CHECK(v2_space_guard_at(space, base + 5 * page_size) == 0);

    /* Guards can be turned off again and the space stays consistent. */
    CHECK(v2_space_set_guard(space, 0) == 0);
    CHECK(v2_space_guard_at(space, base) == 0);
    compare_host_and_space(space, &fake);

    v2_space_destroy(space);
    fake_free(&fake);
    printf("guard  ok  one page after every mapping, never handed out\n");
}

/*
 * MADV_DONTNEED keeps the mapping and promises zeros on the next read.  The
 * host cannot deliver that with a discard hint on Darwin, so the address space
 * releases and recommits the run itself; the page table must be unchanged, and
 * the fake host asserts that a page is never committed while already committed.
 */
static void advise_test(size_t pages, size_t page_size)
{
    struct fake fake;
    struct v2_host host;
    struct v2_space *space = NULL;
    long long mapped;
    long long second;

    fake_init(&fake, pages, page_size);
    host = fake_host(&fake);
    CHECK(v2_space_create(&space, &host, pages * page_size, page_size, 0, 0) == 0);

    mapped = v2_space_map(space, NULL, 2 * page_size,
                          V2_PROT_READ | V2_PROT_WRITE, V2_MAP_ANON, -1, 0);
    CHECK(mapped > 0);
    second = v2_space_map(space, NULL, page_size, V2_PROT_READ, V2_MAP_ANON,
                          -1, 0);
    CHECK(second > 0);

    CHECK(v2_space_advise(space, (void *)(uintptr_t)mapped, 2 * page_size,
                          V2_MADV_DONTNEED) == 0);
    /* Still mapped, still the same protection, still readable. */
    CHECK(v2_space_check(space, (void *)(uintptr_t)mapped, 2 * page_size,
                         V2_PROT_WRITE) == 0);
    CHECK(v2_space_verify(space) == 0);
    compare_host_and_space(space, &fake);

    /* A range that ends inside the second mapping must not disturb it. */
    CHECK(v2_space_advise(space, (void *)(uintptr_t)mapped, page_size,
                          V2_MADV_DONTNEED) == 0);
    CHECK(v2_space_check(space, (void *)(uintptr_t)second, page_size,
                         V2_PROT_READ) == 0);
    compare_host_and_space(space, &fake);

    v2_space_destroy(space);
    fake_free(&fake);
    printf("advise ok  DONTNEED keeps the mapping and the protection\n");
}

int main(int argc, char **argv)
{
    int status = 0;

    guard_test(64, 0x1000);
    advise_test(64, 0x1000);
    if (argc >= 3 && strcmp(argv[1], "--trace") == 0) {
        for (int index = 2; index < argc; index++) {
            status |= replay(argv[index]);
        }
    } else if (argc >= 3 && strcmp(argv[1], "--random") == 0) {
        int operations = atoi(argv[2]);
        uint64_t seed = argc >= 4 ? strtoull(argv[3], NULL, 0) : 1;

        status |= random_test(seed, operations, 2048, 0x4000, 0);
        status |= random_test(seed + 1, operations, 256, 0x4000, 0);
        status |= random_test(seed + 2, operations, 4096, 0x1000, 0);
    } else if (argc >= 3 && strcmp(argv[1], "--guard-random") == 0) {
        /*
         * The same driver with guards armed.  This is the case the device
         * build runs, and the allocator has to keep every invariant with one
         * page withheld after every mapping -- including when the space is
         * nearly full and the guard has to be dropped for a mapping to fit.
         */
        int operations = atoi(argv[2]);
        uint64_t seed = argc >= 4 ? strtoull(argv[3], NULL, 0) : 1;

        status |= random_test(seed, operations, 2048, 0x4000, 1);
        status |= random_test(seed + 1, operations, 256, 0x4000, 1);
        status |= random_test(seed + 2, operations, 4096, 0x1000, 2);
    } else {
        fprintf(stderr,
                "usage: %s --trace FILE... | --random OPS [SEED]\n", argv[0]);
        return 2;
    }
    if (status == 0) {
        printf("all checks passed (%u assertions)\n", g_checks);
    }
    return status;
}
